/**
 * Range bounds are stored as canonical `toISOString()` text, so a bound is
 * normalised to that form before anything compares it.
 */
const instantSchema = isoTimestampSchema.transform((value) =>
  toIsoTimestamp(value),
);

/** Both ends of a range are inclusive, so only a range that ends before it starts is refused. */
function isOrderedRange(range: {
  since?: IsoTimestamp;
  until?: IsoTimestamp;
}): boolean {
  if (range.since === undefined || range.until === undefined) return true;
  return Date.parse(range.since) <= Date.parse(range.until);
}

