import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import {
  collectActivityRange,
  exportActivity,
  listActivity,
  registerActivityListeners,
} from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratch-audit", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scratch: activity audit", () => {
  it("records every reported action once, against the right project and actor", async () => {
    const orgId = tenant.org.id;
    const admin = tenant.actors.admin;
    const member = tenant.actors.member;
    const proj = tenant.project.id;

    const other = await projectService.createProject(admin, {
      orgId,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await projectService.updateProject(admin, {
      orgId,
      projectId: proj,
      name: "Renamed project",
    } as never);

    const issue = await issueService.createIssue(
      member,
      issueInput(orgId, proj, { title: "Audit me" }),
    );
    await issueService.changeIssueStatus(member, {
      orgId,
      issueId: issue.id,
      status: "in_progress",
    });
    await issueService.assignIssue(member, {
      orgId,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });
    await issueService.updateIssue(member, {
      orgId,
      issueId: issue.id,
      title: "Audit me again",
    } as never);

    const comment = await commentService.createComment(member, {
      orgId,
      issueId: issue.id,
      body: "hello",
      parentId: null,
      mentionedUserIds: [],
    } as never);
    await commentService.updateComment(member, {
      orgId,
      commentId: comment.id,
      body: "hello, edited",
    } as never);
    await commentService.deleteComment(member, {
      orgId,
      commentId: comment.id,
    } as never);
    await issueService.archiveIssue(admin, orgId, issue.id);

    const elsewhere = await issueService.createIssue(
      member,
      issueInput(orgId, other.id, { title: "Elsewhere" }),
    );
    await issueService.changeIssueStatus(member, {
      orgId,
      issueId: elsewhere.id,
      status: "in_progress",
    });

    const feed = await listActivity(admin, {
      orgId,
      projectId: proj,
      limit: 100,
      cursor: null,
    });
    const actions = feed.items.map((event) => event.action).sort();
    console.log("PROJECT FEED", actions);

    expect(actions).toEqual(
      [
        "comment.created",
        "comment.deleted",
        "comment.updated",
        "issue.archived",
        "issue.assigned",
        "issue.created",
        "issue.status_changed",
        "issue.updated",
        "project.updated",
      ].sort(),
    );
    expect(feed.items.every((event) => event.projectId === proj)).toBe(true);

    const assigned = feed.items.find((event) => event.action === "issue.assigned");
    expect(assigned?.actorId).toBe(member.userId);
    expect(assigned?.metadata).toMatchObject({ assigneeId: tenant.userIds.admin });

    const status = feed.items.find((event) => event.action === "issue.status_changed");
    expect(status?.metadata).toEqual({ from: "backlog", to: "in_progress" });

    const everything = await listActivity(admin, {
      orgId,
      limit: 100,
      cursor: null,
    });
    expect(everything.items.some((event) => event.projectId === other.id)).toBe(true);
    expect(
      everything.items.filter((event) => event.action === "issue.created"),
    ).toHaveLength(2);
  });

  it("stamps the time the action happened and keeps both range ends", async () => {
    const orgId = tenant.org.id;
    const admin = tenant.actors.admin;
    const member = tenant.actors.member;

    await emit("issue.updated", {
      orgId,
      actorId: member.userId,
      occurredAt: "2020-01-01T10:00:00Z" as never,
      issueId: "iss-late" as never,
      projectId: tenant.project.id,
      changedFields: ["title"],
    });

    const sameInstant = await listActivity(admin, {
      orgId,
      action: ["issue.updated"],
      since: "2020-01-01T10:00:00Z" as never,
      until: "2020-01-01T10:00:00.000Z" as never,
      limit: 100,
      cursor: null,
    });
    expect(sameInstant.items).toHaveLength(1);
    expect(sameInstant.items[0]?.occurredAt).toBe("2020-01-01T10:00:00.000Z");

    await expect(
      listActivity(admin, {
        orgId,
        since: "2020-02-01T00:00:00.000Z" as never,
        until: "2020-01-01T00:00:00.000Z" as never,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toThrow();

    await expect(
      exportActivity(admin, {
        orgId,
        since: "2020-02-01T00:00:00.000Z" as never,
        until: "2020-01-01T00:00:00.000Z" as never,
        format: "json",
      }),
    ).rejects.toThrow();

    const exported = JSON.parse(
      await exportActivity(admin, {
        orgId,
        since: "2020-01-01T10:00:00Z" as never,
        until: "2020-01-01T10:00:00Z" as never,
        format: "json",
      }),
    ) as { summary: string }[];
    expect(exported).toHaveLength(1);
  });

  it("exports every entry in the range across pages, newest first, with no duplicates", async () => {
    const orgId = tenant.org.id;
    const admin = tenant.actors.admin;

    for (let i = 0; i < 130; i += 1) {
      const occurredAt =
        i < 60
          ? "2031-05-05T12:00:00.000Z"
          : new Date(Date.UTC(2031, 4, 5, 12, 0, 0, i)).toISOString();
      await emit("project.created", {
        orgId,
        actorId: admin.userId,
        occurredAt: occurredAt as never,
        projectId: tenant.project.id,
        name: `Bulk ${i}`,
        slug: `bulk-${i}`,
      });
    }

    const rows = JSON.parse(
      await exportActivity(admin, {
        orgId,
        since: "2031-01-01T00:00:00.000Z" as never,
        until: "2031-12-31T23:59:59.999Z" as never,
        format: "json",
      }),
    ) as { id: string; occurredAt: string; metadata: unknown }[];

    expect(rows).toHaveLength(130);
    expect(new Set(rows.map((row) => row.id)).size).toBe(130);
    for (let i = 1; i < rows.length; i += 1) {
      expect(rows[i - 1]!.occurredAt >= rows[i]!.occurredAt).toBe(true);
    }

    const viaCollect = await collectActivityRange(admin, {
      orgId,
      since: "2031-01-01T00:00:00.000Z" as never,
      until: "2031-12-31T23:59:59.999Z" as never,
    });
    expect(viaCollect).toHaveLength(130);

    const otherOrg = await createTenant("scratch-audit-other", "growth");
    const foreign = await collectActivityRange(otherOrg.actors.admin, {
      orgId: otherOrg.org.id,
      since: "2031-01-01T00:00:00.000Z" as never,
      until: "2031-12-31T23:59:59.999Z" as never,
    });
    expect(foreign).toHaveLength(0);
  });

  it("records member and flag events that were previously missing", async () => {
    const orgId = tenant.org.id;
    const admin = tenant.actors.admin;

    await emit("member.joined", {
      orgId,
      actorId: tenant.userIds.viewer,
      occurredAt: "2032-01-01T00:00:00.000Z" as never,
      memberId: "mem-1" as never,
      userId: tenant.userIds.viewer,
      role: "viewer",
    });
    await emit("member.removed", {
      orgId,
      actorId: admin.userId,
      occurredAt: "2032-01-01T00:00:01.000Z" as never,
      memberId: "mem-1" as never,
      userId: tenant.userIds.viewer,
    });
    await emit("flag.toggled", {
      orgId,
      actorId: admin.userId,
      occurredAt: "2032-01-01T00:00:02.000Z" as never,
      flag: "csv_export" as never,
      enabled: false,
    });

    const page = await listActivity(admin, {
      orgId,
      since: "2032-01-01T00:00:00.000Z" as never,
      until: "2032-01-01T00:00:02.000Z" as never,
      limit: 100,
      cursor: null,
    });
    expect(page.items.map((event) => event.action).sort()).toEqual([
      "flag.toggled",
      "member.joined",
      "member.removed",
    ]);
    const joined = page.items.find((event) => event.action === "member.joined");
    expect(joined?.actorId).toBe(tenant.userIds.viewer);
  });
});

